    ('L23_V025', 505.670, 517.276, N'MUỐN CHỌN PHƯƠNG ÁN THI ĐẤU AN TOÀN NÊN ĐÃ NẰM Ở VỊ TRÍ TRÊN ĐẦU VÀ KHI KHÔNG ĐỦ HƠI ĐỂ TUNG NƯỚC RÚT THÌ ANH ĐÃ NHẢ LẠI CHO TAY ĐUA CỦA SÁU HAI MƯƠI CHÂU THẾ VĨNH LONG'),
    ('L23_V025', 517.350, 529.340, N'KHI MÀ PETER CIC THÌ Ở PHÍA TRÊN THÌ ANH SẼ KHÔNG PHẢI CHỊU SỰ TÁC ĐỘNG CỦA BẤT KỲ MỘT TAY ĐUA NÀO KHÁC VÀ NHƯ VẬY THÌ VỊ TRÍ CỦA PETER CNOP SẼ AN TOÀN VỀ ĐÍCH ĐỂ BẢO VỆ THÀNH QUẢ'),
    ('L23_V025', 529.414, 535.068, N'MỘT TÌNH HUỐNG MÀ NẾU RICHUNO ĐỦ HƠI THÌ ANH CÓ THỂ BĂNG THẲNG VỀ ĐÍCH'),
    ('L23_V025', 535.142, 543.900, N'KHI MÀ ÁO VÀNG ĐÃ Ở VỊ TRÍ ĐẦU TIÊN TỪ MỘT KI LÔ MÉT CUỐI KHI MÀ ĐOÀN ĐUA RẼ TỪ ĐƯỜNG NGUYỄN BỈNH KHIÊM SANG ĐƯỜNG LÊ DUẨN'),
    ('L23_V025', 543.974, 549.628, N'NHƯNG CÒN NẾU KHÔNG ĐỦ HƠI THÌ PETER RICONOV VẪN AN TOÀN BẢO VỆ ĐƯỢC ÁO VÀNG VÀ ÁO XANH'),
    ('L23_V025', 549.702, 564.860, N'VÀ Ở PHẦN CÒN LẠI KHI MÀ MARTIN LÁT Ở NGAY Ở PHÍA SAU PETER RICONOV ĐƯỢC SỰ HỖ TRỢ CỦA ĐỒNG ĐỘI MICROM THÌ TAY ĐUA CHÂN RÚT NGƯỜI ESTONIA TAY ĐUA TỪNG THI ĐẤU Ở LA VU ANH TA MỘT CHÂN RÚT ĐẲNG CẤP RĂNG TUA ĐÃ KHÔNG BỎ LỠ CƠ HỘI'),
    ('L23_V025', 564.934, 573.148, N'LÊ NGUYỆT MINH CŨNG ĐÃ RẤT NỖ LỰC ĐEO BÁM NHƯNG KHÔNG THỂ SÁNH BẰNG VỚI SỰ BỨT PHÁ CỦA MẶT TILT'),
    ('L23_V025', 573.222, 583.196, N'VÀ BÊN CẠNH ĐẲNG CẤP CỦA TÀI ĐỘI NGƯỜI ESTONIA THÌ MAI NƯỚC ĐÚC CŨNG CHỨNG KIẾN ĐƯỢC KHẢ NĂNG NƯỚC ĐÚC TUYỆT VỜI VÀ NỖ LỰC PHI THƯỜNG CỦA CÁC CHÂN NƯỚC ĐÚC VIỆT NAM'),
    ('L23_V025', 583.270, 590.620, N'VỚI LÊ NGUYỆT MÌNH VỚI NGUYỄN VĂN BÌNH HOÀNG VĂN CƯỜNG CŨNG ĐÃ NỖ LỰC ĐỂ CẠNH TRANH VÀ CÓ MẶT TRONG NĂM HÀNG ĐẦU CỦA CHẶNG ĐUA NGÀY HÔM NAY'),
    ('L23_V025', 590.694, 595.740, N'CÓ LẼ NHƯ LÀ VỀ NHẤT THÌ KHÔNG PHẢI BÀN RỒI VỀ NHÌ LÀ LÊ NGỌC MINH'),
    ('L23_V025', 595.814, 602.940, N'VỀ THỨ BA LÀ VẬN ĐỘNG VIÊN HOÀNG VĂN CƯỜNG VÀ VỀ THỨ TƯ LÀ NGUYỄN VĂN BÌNH THỨ NĂM CÓ VẺ NHƯ LÀ SAPANOBY KHỚP'),
    ('L23_V025', 603.014, 608.060, N'THEO QUAN SÁT CHÚNG TÔI VÀ HÃY ĐỂ Ý KHI MÀ MARTIN LÁCH VỀ ĐÍCH'),
    ('L23_V025', 608.134, 616.604, N'ÁO VÀNG PETER RICONOS Ở PHÍA SAU ĐÃ CÓ ĐỘNG TÁC ĂN MỪNG ĐÓ LÀ ĐỘNG TÁC ĂN MỪNG KHI ANH AN TOÀN BẢO VỆ ĐƯỢC THÀNH QUẢ CHO CÁ NHÂN VÀ CHO TẬP THỂ AN GIANG'),
    ('L23_V025', 616.678, 621.724, N'<'),
    ('L23_V025', 621.894, 629.148, N'MỘT CUỘC ĐUA TUYỆT VỜI KHI SỰ KỊCH TÍNH SỰ HẤP DẪN ĐÃ ĐƯỢC CÁC TAY ĐUA NỖ LỰC THỂ HIỆN NGAY TỪ CHẶNG ĐUA ĐẦU TIÊN'),
    ('L23_V025', 629.222, 638.332, N'CHẶNG ĐUA VÒNG QUANH THÀNH PHỐ ĐIỆN BIÊN PHỦ VÀO NGÀY BA THÁNG TƯ VÀ KHÉP LẠI BẰNG MỘT MÀN CẠNH TRANH NƯỚC TRÚC HẤP DẪN TRƯỚC HỘI TRƯỜNG THỐNG NHẤT THÀNH PHỐ HỒ CHÍ MINH VÀO TRƯA NGÀY BA MƯƠI THÁNG TƯ LỊCH SỬ'),
    ('L23_V025', 638.406, 643.452, N'EM'),
    ('L23_V025', 646.470, 651.516, N'MÀN ĂN MỪNG VỚI ĐỘNG TÁC ĐƠN GIẢN RẤT QUEN THUỘC CỦA MARTIN LÁT MỖI LẦN GIÀNH CHIẾN THẮNG CHẶN'),
    ('L23_V025', 654.054, 661.052, N'VÀ SAU KHI TẤT CẢ ĐÃ VỀ ĐÍCH AN TOÀN TRƯỚC HỘI TRƯỜNG ĐÔNG NHẤT THÀNH PHỐ HỒ CHÍ MINH THÌ LÚC NÀY ĐOÀN ĐUA CÚP TRUYỀN HÌNH THÀNH PHỐ HỒ CHÍ MINH CŨNG SẼ DI CHUYỂN'),
    ('L23_V025', 661.126, 666.684, N'THEO TRỤC ĐƯỜNG NGUYỄN THỊ MINH KHAI ĐỂ VỀ ĐẾN ĐÀI TRUYỀN HÌNH THÀNH PHỐ HỒ CHÍ MINH Ở ĐƯỜNG ĐINH TIÊN HOÀNG'),
    ('L23_V025', 666.758, 676.476, N'TRƯỚC KHI ĐẾN VỚI BUỔI LỄ TRAO GIẢI VÀ BẾ MẠC CUỘC ĐUA XE ĐẠP TOÀN QUỐC TRÊN CÚP TRUYỀN HÌNH THÀNH PHỐ HỒ CHÍ MINH NÔNG SÔNG LIỀN MỘT GIẢI KỶ NIỆM BẢY MƯƠI NĂM CHIẾN THẮNG ĐIỆN BIÊN PHỦ LẦN THỨ BA MƯƠI SÁU HAI NGÀN HAI'),
    ('L23_V025', 676.550, 681.596, N'HÔM NAY'),
    ('L23_V025', 803.718, 808.764, N'ANH'),
    ('L23_V025', 819.462, 824.508, N'CHÀO'),
    ('L23_V025', 824.582, 829.628, N'CHÀO');
