-- =====================================================================
-- 09. Dữ liệu mẫu, lô L23 (sinh tự động bởi `footage sample`)
--   organizations 5, collections 5, videos 25, keyframes 5913, ocr_texts 3976, asr_segments 1238, requests 120, users 5, selections 60, licenses 30
-- Nguồn video: bộ video tiếng Việt công khai (tường thuật đua xe đạp); khung
-- hình, chữ trên hình (OCR) và lời nói (ASR) do nhóm trích xuất; yêu cầu mẫu
-- do nhóm viết và xác minh vị trí đúng.
-- Đơn vị, bộ sưu tập khác, bạn đọc, trạng thái và giấy phép là dữ liệu MINH HOẠ
-- (tên có chữ "mẫu"); chủ đề được gắn theo luật trên lời nói thật.
-- Tài khoản demo: admin / Admin@123, thuthu1 / Thuthu@123, bandoc1 / Bandoc@123, nghiencuu1 / Nghiencuu@123, sinhvien1 / Sinhvien@123
--   (chỉ để demo, đổi mật khẩu trước khi dùng thật)
-- =====================================================================
SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;
SET NOCOUNT ON;
GO

GO

SELECT v.collection_code, v.title, o.organization_id, v.access_level, v.description
FROM (VALUES
    ('DXD', N'Tường thuật đua xe đạp truyền hình', 'LIB', 'restricted', N'Lô L23 của một bộ dữ liệu video tiếng Việt công khai: các đoạn tường thuật một giải đua xe đạp. Khung hình, chữ trên hình (OCR) và lời nói (ASR) do nhóm trích xuất.'),
    ('TV-A-TS', N'Bản tin thời sự lưu trữ (minh hoạ, chưa nạp video)', 'TV-A', 'restricted', N''),
    ('PRESS-B-PS', N'Phóng sự video (minh hoạ, chưa nạp video)', 'PRESS-B', 'restricted', N''),
    ('UNI-C-BG', N'Bài giảng video (minh hoạ, chưa nạp video)', 'UNI-C', 'open', N''),
    ('MUS-D-HV', N'Hiện vật số hoá (minh hoạ, chưa nạp video)', 'MUS-D', 'open', N'')
) AS v (collection_code, title, org_code, access_level, description)
JOIN dbo.organizations o ON o.org_code = v.org_code;
GO

