-- Gắn chủ đề theo luật: video có ít nhất một đoạn lời nói (đã bỏ dấu)
-- khớp mẫu của chủ đề.
SELECT DISTINCT a.video_id, t.topic_id
FROM (VALUES
    (N'Đua xe đạp', N'%chang dua%'),
    (N'Đua xe đạp', N'%vong dua%'),
    (N'Đua xe đạp', N'%tay dua%'),
    (N'Nước rút', N'%nuoc rut%'),
    (N'Tấn công và bứt phá', N'%tan cong%'),
    (N'Tấn công và bứt phá', N'%but pha%'),
    (N'Chiến thuật đồng đội', N'%may keo%'),
    (N'Chiến thuật đồng đội', N'%chien thuat%'),
    (N'Về đích', N'%ve dich%'),
    (N'Về đích', N'%vach dich%'),
    (N'Áo vàng', N'%ao vang%'),
    (N'Vĩnh Long', N'%vinh long%'),
    (N'TP. Hồ Chí Minh', N'%ho chi minh%'),
    (N'An Giang', N'%an giang%'),
    (N'Đồng Tháp', N'%dong thap%'),
    (N'Đồng Nai', N'%dong nai%'),
    (N'Quay flycam', N'%flycam%'),
    (N'Đồ hoạ theo dõi chuyển động', N'%cong nghe theo doi%'),
    (N'Đồ hoạ theo dõi chuyển động', N'%theo doi chuyen dong%')
) AS rule_list (topic_name, pattern)
JOIN dbo.topics t        ON t.topic_name = rule_list.topic_name
JOIN dbo.asr_segments a  ON a.text_folded LIKE rule_list.pattern;
GO

