SELECT u.user_id, r.role_id
FROM (VALUES
    ('admin', 'admin'),
    ('thuthu1', 'librarian'),
    ('bandoc1', 'reader'),
    ('nghiencuu1', 'reader'),
    ('sinhvien1', 'reader')
) AS v (username, role_name)
JOIN dbo.users u ON u.username = v.username
JOIN dbo.roles r ON r.role_name = v.role_name;
GO

